/* RedRoom Fitness — Global Styles */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Oswald:wght@400;500;600;700&display=swap');

:root {
  --red: #FF0000;
  --charcoal: #141414;
  --white: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-300: #D4D4D4;
  --gray-500: #737373;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--charcoal);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Typography */
.font-display {
  font-family: var(--font-display);
}

.font-body {
  font-family: var(--font-body);
}

/* Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 2px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: all 0.25s ease;
}

.btn-primary {
  background-color: var(--red);
  color: var(--white);
  border-color: var(--red);
}

.btn-primary:hover {
  background-color: #cc0000;
  border-color: #cc0000;
}

.btn-outline {
  background-color: transparent;
  color: var(--white);
  border-color: var(--white);
}

.btn-outline:hover {
  background-color: var(--white);
  color: var(--charcoal);
}

.btn-outline-red {
  background-color: transparent;
  color: var(--red);
  border-color: var(--red);
}

.btn-outline-red:hover {
  background-color: var(--red);
  color: var(--white);
}

/* Top Bar */
.top-bar {
  background-color: var(--red);
  color: var(--white);
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.top-bar a {
  text-decoration: underline;
  font-weight: 600;
  margin-left: 0.25rem;
}

/* Navbar */
.navbar {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-800);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--white);
}

.logo span {
  color: var(--red);
}

.nav-links {
  display: none;
  align-items: center;
  gap: 1.75rem;
}

.nav-links a {
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gray-300);
  transition: color 0.2s ease;
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
}

.nav-links a.active {
  border-bottom: 2px solid var(--red);
  padding-bottom: 2px;
}

.nav-utility {
  display: none;
  align-items: center;
  gap: 1rem;
}

.nav-utility a {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--white);
}

.nav-utility .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.75rem;
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
}

.mobile-menu {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background-color: var(--gray-900);
  border-bottom: 1px solid var(--gray-800);
  padding: 1.5rem;
  flex-direction: column;
  gap: 1rem;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu a {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gray-300);
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--gray-800);
}

.mobile-menu a:hover,
.mobile-menu a.active {
  color: var(--white);
}

/* Hero */
.hero {
  position: relative;
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.35);
  z-index: 0;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(20,20,20,0.3) 0%, rgba(20,20,20,0.7) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 900px;
  padding: 2rem 1.5rem;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.05;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  font-weight: 400;
  color: var(--gray-300);
  max-width: 640px;
  margin: 0 auto 2rem;
  line-height: 1.6;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

/* Section */
.section {
  padding: 5rem 0;
}

.section-alt {
  background-color: var(--gray-900);
}

.section-heading {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 1rem;
  line-height: 1.15;
}

.section-body {
  font-size: 1.0625rem;
  color: var(--gray-300);
  max-width: 640px;
  line-height: 1.7;
}

/* Two Ways */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 3rem;
}

.two-way-card {
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  padding: 2.5rem;
  transition: border-color 0.3s ease, transform 0.3s ease;
}

.two-way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.two-way-card h3 {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 1rem;
  letter-spacing: 0.04em;
}

.two-way-card h3 span {
  color: var(--red);
}

.two-way-card p {
  color: var(--gray-300);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* Studio Experience */
.studio-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
  align-items: center;
}

.studio-visual {
  position: relative;
  aspect-ratio: 16/10;
  background-color: var(--gray-800);
  overflow: hidden;
}

.studio-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.6);
}

/* Free Trial CTA */
.free-trial {
  background-color: var(--red);
  text-align: center;
  padding: 4rem 1.5rem;
}

.free-trial h2 {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 1.5rem;
}

.free-trial .btn-outline {
  border-color: var(--white);
  color: var(--white);
}

.free-trial .btn-outline:hover {
  background-color: var(--white);
  color: var(--red);
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  position: relative;
}

.carousel-slide img {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  filter: brightness(0.55);
}

.carousel-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 3rem 1.5rem 1.5rem;
  background: linear-gradient(to top, rgba(20,20,20,0.95) 0%, transparent 100%);
}

.carousel-caption h3 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: rgba(20,20,20,0.7);
  border: 1px solid var(--gray-700);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease;
  z-index: 10;
}

.carousel-nav:hover {
  background-color: var(--red);
  border-color: var(--red);
}

.carousel-prev { left: 1rem; }
.carousel-next { right: 1rem; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--gray-700);
  border: none;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.carousel-dot.active {
  background-color: var(--red);
}

/* Newsletter */
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 480px;
  margin-top: 1.5rem;
}

.newsletter-form input {
  flex: 1;
  padding: 0.875rem 1rem;
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  outline: none;
  transition: border-color 0.2s ease;
}

.newsletter-form input:focus {
  border-color: var(--red);
}

.newsletter-form input::placeholder {
  color: var(--gray-500);
}

.newsletter-form .error {
  color: #ff6b6b;
  font-size: 0.8125rem;
  margin-top: -0.5rem;
}

.newsletter-form .success {
  color: #4ade80;
  font-size: 0.9375rem;
  font-weight: 500;
}

/* Footer */
.footer {
  background-color: var(--gray-900);
  border-top: 1px solid var(--gray-800);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
  color: var(--white);
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-500);
  transition: color 0.2s ease;
}

.footer-col a:hover {
  color: var(--white);
}

.country-select {
  margin-top: 0.5rem;
  position: relative;
}

.country-select select {
  appearance: none;
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  color: var(--white);
  padding: 0.5rem 2.5rem 0.5rem 0.75rem;
  font-family: var(--font-body);
  font-size: 0.875rem;
  cursor: pointer;
  width: 100%;
  max-width: 240px;
}

.country-select::after {
  content: '▼';
  position: absolute;
  right: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.625rem;
  color: var(--gray-500);
  pointer-events: none;
}

.footer-bottom {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--gray-800);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
  text-align: center;
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* Toggle */
.toggle-group {
  display: inline-flex;
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  overflow: hidden;
}

.toggle-btn {
  padding: 0.75rem 1.75rem;
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: none;
  border: none;
  color: var(--gray-500);
  cursor: pointer;
  transition: all 0.25s ease;
}

.toggle-btn.active {
  background-color: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  margin-top: 2rem;
  animation: fadeIn 0.35s ease;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Table */
.data-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.5rem;
}

.data-table th,
.data-table td {
  padding: 1rem 1.25rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-800);
}

.data-table th {
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-500);
  background-color: var(--gray-900);
}

.data-table td {
  font-size: 0.9375rem;
  color: var(--gray-300);
}

.data-table tr:hover td {
  background-color: rgba(255, 0, 0, 0.04);
}

/* Instructor Cards */
.instructor-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  margin-top: 2rem;
}

.instructor-card {
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  overflow: hidden;
  transition: border-color 0.3s ease, transform 0.3s ease;
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background-color: var(--gray-700);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.instructor-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(0.3) brightness(0.85);
  transition: filter 0.3s ease;
}

.instructor-card:hover .instructor-photo img {
  filter: grayscale(0) brightness(1);
}

.instructor-info {
  padding: 1.25rem;
}

.instructor-info h3 {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 0.25rem;
}

.instructor-info p {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: 1rem;
}

.instructor-info a {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  transition: color 0.2s ease;
}

.instructor-info a:hover {
  color: var(--white);
}

/* Filter */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.filter-btn {
  padding: 0.5rem 1rem;
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  color: var(--gray-500);
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-btn:hover,
.filter-btn.active {
  background-color: var(--red);
  border-color: var(--red);
  color: var(--white);
}

/* Accordion */
.accordion {
  border-top: 1px solid var(--gray-800);
  margin-top: 2rem;
}

.accordion-item {
  border-bottom: 1px solid var(--gray-800);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
  text-align: left;
}

.accordion-header h3 {
  font-family: var(--font-display);
  font-size: 1.0625rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  padding-right: 1rem;
}

.accordion-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.3s ease;
  color: var(--red);
}

.accordion-item.open .accordion-icon {
  transform: rotate(45deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.accordion-item.open .accordion-body {
  max-height: 300px;
  padding-bottom: 1.25rem;
}

.accordion-body p {
  color: var(--gray-300);
  line-height: 1.7;
  font-size: 0.9375rem;
}

/* Feature Cards */
.feature-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  margin-top: 2rem;
}

.feature-card {
  background-color: var(--gray-800);
  border: 1px solid var(--gray-700);
  padding: 2rem;
  transition: border-color 0.3s ease;
}

.feature-card:hover {
  border-color: var(--red);
}

.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 0.75rem;
  color: var(--white);
}

.feature-card h3 span {
  color: var(--red);
}

.feature-card p {
  color: var(--gray-300);
  line-height: 1.7;
  font-size: 0.9375rem;
}

/* Responsive */
@media (min-width: 640px) {
  .two-ways-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .newsletter-form {
    flex-direction: row;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }

  .nav-utility {
    display: flex;
  }

  .mobile-menu-btn {
    display: none;
  }

  .studio-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

@media (min-width: 1024px) {
  .instructor-grid {
    grid-template-columns: repeat(4, 1fr);
  }

  .feature-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

// RedRoom Fitness — Global Scripts

document.addEventListener('DOMContentLoaded', function () {
  initMobileMenu();
  initCarousels();
  initAccordions();
  initToggles();
  initNewsletters();
  initInstructorFilters();
});

/* Mobile Menu */
function initMobileMenu() {
  const btn = document.querySelector('.mobile-menu-btn');
  const menu = document.querySelector('.mobile-menu');
  if (!btn || !menu) return;

  btn.addEventListener('click', function () {
    menu.classList.toggle('open');
    const isOpen = menu.classList.contains('open');
    btn.setAttribute('aria-expanded', String(isOpen));
  });

  // Close on link click
  menu.querySelectorAll('a').forEach(function (link) {
    link.addEventListener('click', function () {
      menu.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
    });
  });
}

/* Carousels */
function initCarousels() {
  document.querySelectorAll('.carousel').forEach(function (carousel) {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const prevBtn = carousel.querySelector('.carousel-prev');
    const nextBtn = carousel.querySelector('.carousel-next');
    const dotsContainer = carousel.querySelector('.carousel-dots');
    if (!track || slides.length === 0) return;

    let current = 0;
    const total = slides.length;

    function goTo(index) {
      if (index < 0) index = total - 1;
      if (index >= total) index = 0;
      current = index;
      track.style.transform = 'translateX(-' + (current * 100) + '%)';
      updateDots();
    }

    function updateDots() {
      if (!dotsContainer) return;
      dotsContainer.querySelectorAll('.carousel-dot').forEach(function (dot, i) {
        dot.classList.toggle('active', i === current);
      });
    }

    if (prevBtn) prevBtn.addEventListener('click', function () { goTo(current - 1); });
    if (nextBtn) nextBtn.addEventListener('click', function () { goTo(current + 1); });

    if (dotsContainer) {
      dotsContainer.querySelectorAll('.carousel-dot').forEach(function (dot, i) {
        dot.addEventListener('click', function () { goTo(i); });
      });
    }

    // Touch / swipe support
    let startX = 0;
    let isDragging = false;

    carousel.addEventListener('touchstart', function (e) {
      startX = e.touches[0].clientX;
      isDragging = true;
    }, { passive: true });

    carousel.addEventListener('touchmove', function () {
      // no-op, just for completeness
    }, { passive: true });

    carousel.addEventListener('touchend', function (e) {
      if (!isDragging) return;
      const endX = e.changedTouches[0].clientX;
      const diff = startX - endX;
      if (Math.abs(diff) > 40) {
        goTo(current + (diff > 0 ? 1 : -1));
      }
      isDragging = false;
    }, { passive: true });

    // Auto-advance every 6s
    setInterval(function () {
      goTo(current + 1);
    }, 6000);
  });
}

/* Accordions (single-open) */
function initAccordions() {
  document.querySelectorAll('.accordion').forEach(function (accordion) {
    const items = accordion.querySelectorAll('.accordion-item');

    items.forEach(function (item) {
      const header = item.querySelector('.accordion-header');
      if (!header) return;

      header.addEventListener('click', function () {
        const isOpen = item.classList.contains('open');

        // Close all in this accordion
        items.forEach(function (other) {
          other.classList.remove('open');
          const otherHeader = other.querySelector('.accordion-header');
          if (otherHeader) otherHeader.setAttribute('aria-expanded', 'false');
        });

        // Toggle current
        if (!isOpen) {
          item.classList.add('open');
          header.setAttribute('aria-expanded', 'true');
        }
      });
    });
  });
}

/* Toggles (Floor/Treadmill) */
function initToggles() {
  document.querySelectorAll('.toggle-group').forEach(function (group) {
    const buttons = group.querySelectorAll('.toggle-btn');
    const targetName = group.dataset.target;
    if (!targetName) return;

    buttons.forEach(function (btn) {
      btn.addEventListener('click', function () {
        const target = btn.dataset.toggle;

        buttons.forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');

        document.querySelectorAll('[data-toggle-group="' + targetName + '"]').forEach(function (content) {
          content.classList.toggle('active', content.dataset.toggleId === target);
        });
      });
    });
  });
}

/* Newsletter Validation */
function initNewsletters() {
  document.querySelectorAll('.newsletter-form').forEach(function (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      const input = form.querySelector('input[type="email"]');
      const errorEl = form.querySelector('.error');
      const successEl = form.querySelector('.success');
      const email = input.value.trim();

      if (errorEl) errorEl.textContent = '';
      if (successEl) successEl.textContent = '';

      if (!email) {
        if (errorEl) errorEl.textContent = 'Please enter your email address.';
        return;
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        if (errorEl) errorEl.textContent = 'Please enter a valid email address.';
        return;
      }

      if (successEl) {
        successEl.textContent = 'Thanks for subscribing! Check your inbox for confirmation.';
      }
      input.value = '';
    });
  });
}

/* Instructor Filters */
function initInstructorFilters() {
  const filterBar = document.querySelector('.filter-bar');
  const grid = document.querySelector('.instructor-grid');
  if (!filterBar || !grid) return;

  const buttons = filterBar.querySelectorAll('.filter-btn');
  const cards = grid.querySelectorAll('.instructor-card');

  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      const location = btn.dataset.filter;

      buttons.forEach(function (b) { b.classList.remove('active'); });
      btn.classList.add('active');

      cards.forEach(function (card) {
        const cardLocation = card.dataset.location;
        if (!location || location === 'all' || cardLocation === location) {
          card.style.display = '';
          // subtle animation
          card.style.opacity = '0';
          card.style.transform = 'translateY(12px)';
          requestAnimationFrame(function () {
            card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
          });
        } else {
          card.style.display = 'none';
        }
      });
    });
  });
}
